const stdout = $json.stdout || '';
const lines = stdout.split('\n').filter(Boolean);
const mfLine = lines.find((l) => l.startsWith('MF='));
if (!mfLine) return [{ json: { noManifest: true } }];
const manifestFile = mfLine.slice(3).trim();
const runId = (manifestFile.match(/([^/]+)\.txt$/) || [])[1] || 'unknown';
const chunks = [];
for (const l of lines.slice(1)) {
  const m = l.trim().split(/\s+/);
  if (m.length >= 2) chunks.push({ id: m[0], count: parseInt(m[1], 10) || 0 });
}
return [{
  json: {
    manifestFile,
    runId,
    chunks,
    expectedChunks: chunks.length,
    expectedRepos: chunks.reduce((a, c) => a + c.count, 0),
  },
}];

const manifest = $('Parse Manifest').item.json;
const stdout = $json.stdout || '';
const [countsPart, logsPart] = stdout.split('===LOGS===');

const counts = {};
for (const line of (countsPart || '').split('\n')) {
  const m = line.trim().match(/^(transit|internal)\s+(\d+)$/);
  if (m) counts[m[1]] = parseInt(m[2], 10);
}

const logs = [];
for (const line of (logsPart || '').split('\n')) {
  const t = line.trim();
  if (!t) continue;
  try { logs.push(JSON.parse(t)); } catch (e) { /* skip malformed */ }
}

const byRepo = {};
for (const l of logs) byRepo[l.pipeline + ':' + l.repo] = l;
const failedRepos = Object.values(byRepo)
  .filter((l) => l.status !== 'ok')
  .map((l) => ({ pipeline: l.pipeline, repo: l.repo }));

const doneChunks = (counts.transit || 0) + (counts.internal || 0);

return [{
  json: {
    runId: manifest.runId,
    expectedChunks: manifest.expectedChunks,
    expectedRepos: manifest.expectedRepos,
    counts,
    doneChunks,
    missingChunks: Math.max(0, manifest.expectedChunks - doneChunks),
    failedRepos,
    processedRepoLogs: logs.length,
    generatedAt: new Date().toISOString(),
  },
}];

const st = $json;
const rows = [
  '# Repo scan report',
  '',
  '- Run: ' + st.runId,
  '- Generated: ' + st.generatedAt,
  '- Expected repos: ' + st.expectedRepos + ' (' + st.expectedChunks + ' chunks)',
  '- Done chunks: ' + st.doneChunks,
  '- Missing chunks: ' + st.missingChunks,
  '- Failed repos: ' + st.failedRepos.length,
  '',
];
if (st.failedRepos.length) {
  rows.push('## Failed repos', '');
  for (const f of st.failedRepos.slice(0, 200)) rows.push('- [' + f.pipeline + '] ' + f.repo);
}
const markdown = rows.join('\n');
const summary = { ...st, markdown, status: st.missingChunks === 0 && st.failedRepos.length === 0 ? 'complete' : 'incomplete' };
return [{
  json: {
    ...summary,
    jsonBase64: Buffer.from(JSON.stringify(summary)).toString('base64'),
    mdBase64: Buffer.from(markdown).toString('base64'),
  },
}];
